def test_list_documents_respects_limit(repo):
    repo.ensure_user("test", user_id="u1", display_name="Alice")
    for i in range(3):
        repo.create_document(
            "test", document_id=f"d{i}", title=f"t{i}", text="x",
            source_format="text", ingested_by="u1", created_at=100 + i,
            chunks=[{"chunkId": f"c{i}", "text": "x", "seq": 0}],
        )

    rows = repo.list_documents("test", limit=2)

    assert len(rows) == 2

def _pointer(root: dict[str, Any], ref: str) -> dict[str, Any]:
    """Resolve a local JSON pointer (`#/components/schemas/X`, `#/$defs/X`)."""
    if not ref.startswith("#/"):
        raise ValueError(f"non-local $ref {ref!r}: the collector cannot see it")
    node: Any = root
    for part in ref[2:].split("/"):
        node = node[part.replace("~1", "/").replace("~0", "~")]
    return node

def _nest(depth):
    """A `not`-chain of the given nesting depth around one leaf."""
    node = dict(_T)
    for _ in range(depth - 1):
        node = {"kind": "not", "of": [node]}
    return node

def timeout_for_kind(self, kind: str) -> float:
        value = self.timeouts.get(kind)
        if isinstance(value, (int, float)):
            return float(value)
        return _DEFAULT_KIND_TIMEOUTS.get(kind, _DEFAULT_TIMEOUT_FALLBACK)

def resolve_member_kinds(self, ws: str, *, ids: list[str]) -> dict[str, str | None]:
        """id -> 'User' | 'Agent' | None. QUERIES.md §2 (member-kind lookup).

        One round trip covers author validation, mention validation, and role
        derivation (`User → user`, `Agent → assistant` — mapping is service-side).
        """
        if not ids:
            return {}
        res = self._graph(ws).ro_query(
            "UNWIND $ids AS id "
            "OPTIONAL MATCH (u:User  {userId:  id}) "
            "OPTIONAL MATCH (a:Agent {agentId: id}) "
            "RETURN id, CASE WHEN coalesce(u, a) IS NULL THEN null "
            "                ELSE labels(coalesce(u, a))[0] END AS kind",
            {"ids": list(ids)},
        )
        return {row[0]: row[1] for row in res.result_set}

def dispatch(self, name, arguments, *, ctx, run):
        if name == self._fail_tool and not self._raised:
            self._raised = True
            self.dispatched.append((name, arguments))
            raise self._exc
        return super().dispatch(name, arguments, ctx=ctx, run=run)

def create_document(
        self, ws, *, document_id, title, text, source_format,
        ingested_by, created_at, chunks,
    ):
        self.calls.append(("create_document", ws, document_id, ingested_by, chunks))
        if ingested_by in self.agents:
            kind, actor_label = "agent", "Agent"
        elif ingested_by in self.members:
            kind, actor_label = "document", "User"
        else:
            return DocumentWriteStatus(written=False, ingestor_found=False)
        self.documents[document_id] = {
            "documentId": document_id, "title": title, "text": text,
            "sourceFormat": source_format, "sourceKind": kind,
            "status": "processing", "createdAt": created_at,
            "ingestedByKind": actor_label, "ingestedById": ingested_by,
            "chunks": chunks,
        }
        return DocumentWriteStatus(written=True, ingestor_found=True)

def _resolve_path(path: Any, *, ctx: dict[str, Any], step_output: str) -> Any:
    """Resolve a whitelisted `ctx.…` / `output.…` path → the value, or `_MISSING`."""
    if not isinstance(path, str):
        return _MISSING
    head, _, rest = path.partition(".")
    if head == "ctx":
        # A bare `ctx` is not a value — it is the whole run state. Only `ctx.<key>…`
        # resolves, and `validate_cmp` rejects the bare root at publish time to match.
        if not rest:
            return _MISSING
        cursor: Any = ctx
    elif head == "output":
        cursor = step_output if not rest else _load_obj(step_output)
    else:
        return _MISSING
    if not rest:
        return cursor
    for key in rest.split("."):
        if not isinstance(cursor, Mapping) or key not in cursor:
            return _MISSING
        cursor = cursor[key]
    return cursor

def _contains(left: Any, value: Any) -> bool:
    """`value` ∈ the list/str at `path`. A non-container (or an unhashable probe) ⇒ False."""
    if not isinstance(left, (list, tuple, str)):
        return False
    try:
        return value in left
    except TypeError:
        return False

def health(ctx: CallContext = Depends(get_context)):
        # Liveness for probes/CI: proves the process is up AND FalkorDB answers.
        try:
            ok = services.ping(ctx)
        except Exception:
            ok = False
        if not ok:
            raise HTTPException(status_code=503, detail="FalkorDB unreachable")
        return {"status": "ok"}

def call(*args, **kwargs):
                self.calls += 1
                if self.calls > self._after:
                    raise self._exc
                return getattr(self._inner, self._method)(*args, **kwargs)

def _dependency_names(dependant) -> set[str]:
    """Every dependency callable's name on a route, recursively."""
    names = {getattr(dependant.call, "__name__", "")}
    for sub in dependant.dependencies:
        names |= _dependency_names(sub)
    return names

def embed(self, text: str) -> list[float]:
        self.calls += 1
        if self._raise_after is not None and self.calls > self._raise_after:
            raise RuntimeError("simulated embedder crash (interrupt/resume test)")
        seed = (abs(hash(text)) % 997) / 997.0
        return [seed + (i * 0.001) for i in range(self.dim)]

def _read_or_absent(fn: Callable[[], Any], absent: Any = None) -> Any:
    """Read-only probe: a cold graph key or an absent def is 'nothing there'.

    Mirrors `scripts/verify_workflows.sh`'s own `read()` helper byte-for-byte —
    a `WorkflowDefNotFoundError` (both sides absent) or a FalkorDB "empty key"
    `ResponseError` (the `reference`/`ws:{id}` graph key was never created) both
    mean "nothing there yet", not a fault worth a 500.
    """
    try:
        return fn()
    except WorkflowDefNotFoundError:
        return absent
    except ResponseError as exc:
        if "empty key" in str(exc):
            return absent
        raise

def find_due_wait_candidates(self, ws, *, limit):
        candidates = self._repo.find_due_wait_candidates(ws, limit=limit)
        if not self._scanned:
            self._scanned = True
            self._on_scan()
        return candidates

def post_first_message(self, ws, **kw):
        self.calls.append(("post_first_message", kw))
        if self.first_status:
            return self.first_status.pop(0)
        self.heads.add(kw["thread_id"])
        return OK

def set_chunk_embedding(self, ws, *, chunk_id, embedding, expected_dim=None):
        dim = self._dim if expected_dim is None else expected_dim
        if len(embedding) != dim:
            raise EmbeddingDimensionError(f"len {len(embedding)} != {dim}")
        self.chunk_calls.append((ws, chunk_id, tuple(embedding), expected_dim))
        return True

def complete(self, messages: list[ChatMessage]) -> str:
        caught: list[ProviderCallError] = []
        for client in self._clients:
            try:
                return client.complete(messages)
            except ProviderCallError as exc:
                caught.append(exc)
        raise self._exhausted(caught)

def _returned_columns(cypher: str) -> list[str]:
    """The column names a compiled query returns, read from its text (the
    RCA's "every *compiled* multi-row shape"): the items after the last
    `RETURN `, with the tuple-distinct branch's `cN AS \\`expr\\`` mapped back
    to `expr`."""
    tail = cypher.rsplit("RETURN ", 1)[1].removeprefix("DISTINCT ")
    for stop in (" ORDER BY ", " LIMIT "):
        tail = tail.split(stop, 1)[0]
    return [
        item.split(" AS `", 1)[1].removesuffix("`") if " AS `" in item else item
        for item in tail.split(", ")
    ]

def _returns_shape(cls, values: list[str]) -> list[str]:
        for v in values:
            if not (_PROJECTION_RE.fullmatch(v) or _AGGREGATE_RE.fullmatch(v)):
                raise ValueError(
                    f"returns entry {v!r} does not match a projection or aggregate shape"
                )
        return values

def run(self, arguments: dict[str, Any], *, ctx: CallContext,
            run: dict[str, Any]) -> str:
        product_id = arguments.get("productId", "")
        row = self._services.add_cart_item(
            ctx, product_id=product_id, quantity=arguments.get("quantity") or 1,
        )
        if row is None:
            return _product_not_found(product_id)
        return json.dumps({"found": True, **row})

def mcp_constraints(server, seen: set[str] | None = None) -> dict[tuple[str, str, str], Any]:
    """`(tool, argument path, keyword) -> value` for every constraint `server` advertises."""
    found: dict[tuple[str, str, str], Any] = {}
    for tool in asyncio.run(server.list_tools()):
        positions: dict[tuple[str, str], Any] = {}
        schema_constraints(tool.inputSchema, tool.inputSchema, "", positions, seen=seen)
        for (arg, key), value in positions.items():
            found[(tool.name, arg, key)] = value
    return found
